const upsertCustomFieldValue = `-- name: UpsertCustomFieldValue :exec

INSERT INTO ticket_custom_field_values (ticket_id, field_def_id, value, updated_at)
VALUES ($1, $2, $3, NOW())
ON CONFLICT (ticket_id, field_def_id)
DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
`

type UpsertCustomFieldValueParams struct {
	TicketID   uuid.UUID `json:"ticket_id"`
	FieldDefID uuid.UUID `json:"field_def_id"`
	Value      string    `json:"value"`
}

// ── Values ────────────────────────────────────────────────────────────────────
func (q *Queries) UpsertCustomFieldValue(ctx context.Context, arg UpsertCustomFieldValueParams) error {
	_, err := q.db.ExecContext(ctx, upsertCustomFieldValue, arg.TicketID, arg.FieldDefID, arg.Value)
	return err
}
